def linear(n):
    c = 0
    for _ in range(n):
        c += 1
    return c

def quadratic(n):
    c = 0
    for i in range(n):
        for j in range(n):
            c += 1
    return c

def logarithmic(n):
    c = 0
    while n > 1:
        n //= 2
        c += 1
    return c

def pairs(n):
    c = 0
    for i in range(n):
        for j in range(i + 1, n):
            c += 1
    return c

