def lower_bound(a, x):
    lo, hi = 0, len(a)
    while lo < hi:
        mid = (lo + hi) // 2
        if a[mid] < x:
            lo = mid + 1
        else:
            hi = mid
    return lo

def search_range(a, x):
    l = lower_bound(a, x)
    if l == len(a) or a[l] != x:
        return [-1, -1]
    return [l, lower_bound(a, x + 1) - 1]

