from collections import deque

class T:
    def __init__(self, v, l=None, r=None):
        self.v, self.l, self.r = v, l, r

def level_order(root):
    if not root:
        return []
    out, q = [], deque([root])
    while q:
        level = []
        for _ in range(len(q)):
            n = q.popleft()
            level.append(n.v)
            if n.l:
                q.append(n.l)
            if n.r:
                q.append(n.r)
        out.append(level)
    return out

def depth(n):
    return 0 if not n else 1 + max(depth(n.l), depth(n.r))

def inorder(root):
    out, st, cur = [], [], root
    while cur or st:
        while cur:
            st.append(cur)
            cur = cur.l
        cur = st.pop()
        out.append(cur.v)
        cur = cur.r
    return out

def is_bst(n, lo=float("-inf"), hi=float("inf")):
    if not n:
        return True
    if not (lo < n.v < hi):
        return False
    return is_bst(n.l, lo, n.v) and is_bst(n.r, n.v, hi)

