from collections import Counter

def min_window(s, t):
    if not t or len(t) > len(s):
        return ""
    need = Counter(t)
    missing = len(t)
    best = (0, float("inf"))
    l = 0
    for r, ch in enumerate(s):
        if need[ch] > 0:
            missing -= 1
        need[ch] -= 1
        if missing == 0:
            while need[s[l]] < 0:
                need[s[l]] += 1
                l += 1
            if r - l < best[1] - best[0]:
                best = (l, r)
            need[s[l]] += 1
            missing += 1
            l += 1
    return "" if best[1] == float("inf") else s[best[0]:best[1] + 1]

