def count_inv(a):
    def sort(a):
        if len(a) <= 1:
            return a, 0
        m = len(a) // 2
        l, x = sort(a[:m])
        r, y = sort(a[m:])
        merged, i, j, inv = [], 0, 0, x + y
        while i < len(l) and j < len(r):
            if l[i] <= r[j]:
                merged.append(l[i])
                i += 1
            else:
                merged.append(r[j])
                j += 1
                inv += len(l) - i
        merged += l[i:] + r[j:]
        return merged, inv
    return sort(list(a))[1]

def brute(a):
    return sum(1 for i in range(len(a)) for j in range(i + 1, len(a)) if a[i] > a[j])

print(count_inv([2, 4, 1, 3, 5]), count_inv([5, 4, 3, 2, 1]), count_inv([1, 2, 3]), count_inv([]), count_inv([2, 2, 1]))
