class Node:
    def __init__(self, v, nxt=None):
        self.v = v
        self.next = nxt

def build(xs):
    head = None
    for x in reversed(xs):
        head = Node(x, head)
    return head

def to_list(h):
    out = []
    while h:
        out.append(h.v)
        h = h.next
    return out

def reverse(h):
    prev = None
    while h:
        nxt = h.next
        h.next = prev
        prev = h
        h = nxt
    return prev

def has_cycle(h):
    slow = fast = h
    while fast and fast.next:
        slow = slow.next
        fast = fast.next.next
        if slow is fast:
            return True
    return False

